-- Transaction and savepoint names (including variables), WITH MARK and DELAYED_DURABILITY
BEGIN TRAN @t;
SAVE TRAN @s;
ROLLBACK TRAN @s;
COMMIT TRAN @t;
COMMIT WITH (DELAYED_DURABILITY = ON);
COMMIT TRAN t1 WITH (DELAYED_DURABILITY = OFF);
BEGIN DISTRIBUTED TRAN @t;
BEGIN TRAN t WITH MARK 'desc';
COMMIT WORK;
ROLLBACK WORK;
BEGIN TRAN t WITH MARK 'it''s';
BEGIN TRAN @t WITH MARK @d;
